function testIsValidBrackets() {
  // Test cases
  const testCases = [
    { input: '', expected: true, description: 'empty string' },
    { input: 'abc', expected: true, description: 'string with only ordinary characters' },
    { input: '()', expected: true, description: 'simple parentheses' },
    { input: '[]', expected: true, description: 'simple square brackets' },
    { input: '{}', expected: true, description: 'simple curly braces' },
    { input: '(abc)', expected: true, description: 'brackets with ordinary characters' },
    { input: '([{}])', expected: true, description: 'deeply nested brackets' },
    { input: '([)]', expected: false, description: 'mismatched nesting' },
    { input: '({)}', expected: false, description: 'mismatched nesting' },
    { input: '(', expected: false, description: 'unclosed opening bracket' },
    { input: '({[', expected: false, description: 'multiple unclosed opening brackets' },
    { input: ')', expected: false, description: 'extra closing bracket' },
    { input: '())', expected: false, description: 'extra closing bracket' },
    { input: '({[]})', expected: true, description: 'complex valid nesting' },
    { input: '({[}])', expected: false, description: 'complex invalid nesting' },
    { input: null, expected: false, description: 'null input' },
    { input: undefined, expected: false, description: 'undefined input' },
    { input: 123, expected: false, description: 'non-string input' },
    { input: 'a(b[c]d{e}f)g', expected: true, description: 'mixed with ordinary characters' },
    { input: 'a(b[c)d{e}f]g', expected: false, description: 'mixed with invalid nesting' },
    { input: '([]){}', expected: true, description: 'multiple valid bracket pairs' },
    { input: '([)]{}', expected: false, description: 'multiple mismatched bracket pairs' }
  ];

  // Run tests
  let passed = 0;
  for (const testCase of testCases) {
    const result = isValidBrackets(testCase.input);
    if (result === testCase.expected) {
      passed++;
      console.log(`✓ ${testCase.description}: ${result}`);
    } else {
      console.log(`✗ ${testCase.description}: expected ${testCase.expected}, got ${result}`);
    }
  }

  console.log(`\nPassed ${passed} out of ${testCases.length} tests.`);
}

// Run the tests
testIsValidBrackets();
```

### Explanation

**Function Contract:**
- The function `isValidBrackets(s)` checks if all brackets in a string are properly matched and nested.
- Non-bracket characters (anything other than `()[]{}`) are completely ignored during validation.
- For non-string inputs (null, undefined, numbers, etc.), the function returns false.
- The empty string is considered valid (returns true).

**Complexity Analysis:**
- **Time Complexity:** O(n) - We iterate through the string exactly once, performing constant-time operations for each character.
- **Space Complexity:** O(n) in the worst case - When the string consists entirely of opening brackets (e.g., "((((("), we need to store all of them in the stack until we find their closing counterparts.

**Implementation Details:**
1. **Input Validation:** First checks if the input is a string. If not, returns false.
2. **Stack Initialization:** Uses an array as a stack to track opening brackets.
3. **Bracket Pairs:** Uses an object to map opening brackets to their corresponding closing brackets.
4. **Iteration:** For each character in the string:
   - If it's an opening bracket, pushes it onto the stack.
   - If it's a closing bracket, checks if it matches the most recent opening bracket (popped from the stack).
   - Non-bracket characters are skipped.
5. **Final Check:** After processing all characters, checks if the stack is empty (all opening brackets were closed).

**Edge Cases Covered:**
- Empty string (valid)
- String with only ordinary characters (valid)
- Deeply nested brackets (valid if properly nested)
- Extra closing brackets (invalid)
- Unclosed opening brackets (invalid)
- Non-string inputs (invalid)

The test cases cover all these scenarios plus various combinations of valid and invalid bracket nesting with ordinary characters mixed in.

I'll implement both iterative and recursive variants of binary search that return the first occurrence of the target. Here are the complete implementations:

```js
/**
 * Performs an iterative binary search to find the first occurrence of target in a sorted array.
 * @param {Array<number>} sorted - The sorted array to search in (must be sorted in ascending order)
 * @param {number} target - The value to search for
 * @returns {number} The index of the first occurrence of target, or -1 if not found
 * 
 * Requirements:
 * - Time complexity: O(log n)
 * - Space complexity: O(1)
 * - Returns the first occurrence when duplicates exist
 * - Does not mutate the input array
 * - Uses safe midpoint computation: left + Math.floor((right - left) / 2)
 */
function binarySearch(sorted, target) {
    // Validate input
    if (!Array.isArray(sorted)) {
        throw new TypeError('Input must be an array');
    }

    let left = 0;
    let right = sorted.length - 1;
    let result = -1;

    while (left <= right) {
        const mid = left + Math.floor((right - left) / 2);

        if (sorted[mid] === target) {
            // Found target, but continue searching to the left for first occurrence
            result = mid;
            right = mid - 1;
        } else if (sorted[mid] < target) {
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }

    return result;
}

/**
 * Performs a recursive binary search to find the first occurrence of target in a sorted array.
 * @param {Array<number>} sorted - The sorted array to search in (must be sorted in ascending order)
 * @param {number} target - The value to search for
 * @returns {number} The index of the first occurrence of target, or -1 if not found
 * 
 * Requirements:
 * - Time complexity: O(log n)
 * - Space complexity: O(log n) due to recursion stack
 * - Returns the first occurrence when duplicates exist
 * - Does not mutate the input array
 * - Uses safe midpoint computation: left + Math.floor((right - left) / 2)
 * - Safe for null/undefined input (validation in function body)
 */
function binarySearchRecursive(sorted, target) {
    // Validate input
    if (!Array.isArray(sorted)) {
        throw new TypeError('Input must be an array');
    }

    function helper(left, right) {
        if (left > right) {
            return -1;
        }

        const mid = left + Math.floor((right - left) / 2);

        if (sorted[mid] === target) {
            // Found target, but continue searching to the left for first occurrence
            const leftResult = helper(left, mid - 1);
            return leftResult !== -1 ? leftResult : mid;
        } else if (sorted[mid] < target) {
            return helper(mid + 1, right);
        } else {
            return helper(left, mid - 1);
        }
    }

    return helper(0, sorted.length - 1);
}

// Export functions for testing
module.exports = { binarySearch, binarySearchRecursive };
```

### Explanation:

**Binary Search (Iterative):**
1. **Input Requirements:** The input array must be sorted in ascending order. If the array is not sorted, the function will not work correctly.
2. **Handling Absent Target:** If the target is not found, the function returns -1.
3. **Finding First Occurrence:** When the target is found, we continue searching to the left (by adjusting `right = mid - 1`) to ensure we find the first occurrence.
4. **Midpoint Calculation:** Uses the safe formula `left + Math.floor((right - left) / 2)` to prevent potential overflow.
5. **Complexity:** 
   - Time: O(log n) - The search space is halved with each iteration
   - Space: O(1) - Only a few variables are used regardless of input size

**Binary Search (Recursive):**
1. **Input Validation:** The function validates that the input is an array (handles null/undefined safely).
2. **Helper Function:** Uses an inner helper function to perform the recursive search.
3. **Base Case:** When `left > right`, the search space is exhausted and we return -1.
4. **Finding First Occurrence:** Similar to the iterative version, when the target is found, we recursively search the left half to find the first occurrence.
5. **Complexity:**
   - Time: O(log n) - Same as iterative version
   - Space: O(log n) - Due to the recursion stack depth

**Edge Cases:**
- Empty array: Returns -1
- Single element array: Returns 0 if the element matches, otherwise -1
- All elements are the same: Returns 0 (first occurrence)
- Target not present: Returns -1
- Array with duplicates: Returns the index of the first occurrence

Both implementations meet the specified requirements and handle all edge cases appropriately.

Let me trace this script step by step, showing the microtask queue state after each statement that logs or enqueues.

```js
console.log('A')  // Output: A
// Queue after sync: []

Promise.resolve().then(() => {
  console.log('B')
  Promise.resolve().then(() => console.log('C'))
})
// This .then() is on an already-resolved promise, so it queues immediately
// Queue after sync: [B]

queueMicrotask(() => console.log('D'))
// Queue after sync: [B, D]

Promise.resolve().then(() => console.log('E'))
// This .then() is also on an already-resolved promise, so it queues immediately
// Queue after sync: [B, D, E]

setTimeout(() => console.log('F'), 0)
// setTimeout is a macrotask, so it doesn't go to microtask queue
// Queue after sync: [B, D, E]

console.log('G')  // Output: G
// Queue after sync: [B, D, E]

// Now we drain the microtask queue FIFO:
// B runs
console.log('B')  // Output: B
// Inside B's callback, a new .then() is queued
// Queue after B: [D, E, C]

// D runs
console.log('D')  // Output: D
// D doesn't enqueue anything new
// Queue after D: [E, C]

// E runs
console.log('E')  // Output: E
// E doesn't enqueue anything new
// Queue after E: [C]

// C runs
console.log('C')  // Output: C
// C doesn't enqueue anything new
// Queue after C: []

// Macrotask queue (setTimeout)
console.log('F')  // Output: F
```

Final output: A G B D E C F

Explanation:
1. The synchronous code runs first, logging 'A' and 'G'.
2. During synchronous execution, three microtasks are queued: 'B', 'D', and 'E'.
3. The microtask queue is drained FIFO:
   - 'B' runs first, and while running, it queues another microtask 'C' at the back of the queue.
   - 'D' runs next (no new microtasks queued).
   - 'E' runs next (no new microtasks queued).
   - 'C' runs last (queued by 'B').
4. Finally, the macrotask from setTimeout runs, logging 'F'.

The key observation is that when 'B' runs, it queues 'C' at the back of the queue, so 'C' only runs after all other microtasks that were already queued ('D' and 'E') have executed. This demonstrates the strict FIFO nature of microtask queueing.
